<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {LoaderCircle,RotateCcw,X} from 'lucide-vue-next';
import type {BranchItem,RepositoryVersionRestorePreview,RepositoryVersionRestoreResult} from '@oxen/shared';
import {ApiError,post,request} from '../api';
import {useAppStore} from '../stores/app';
const props=defineProps<{base:string;branch:string;targetCommit:string}>(),emit=defineEmits<{close:[];restored:[RepositoryVersionRestoreResult]}>(),app=useAppStore();
const loading=ref(false),busy=ref(false),error=ref(''),uncertain=ref(false),uncertainId=ref(''),preview=ref<RepositoryVersionRestorePreview>(),confirmation=ref(''),message=ref(''),filter=ref(''),page=ref(1);
const project=computed(()=>props.base.split('/').slice(-2).map(decodeURIComponent).join('/')),confirmValue=computed(()=>project.value+'@'+props.branch);
const filtered=computed(()=>preview.value?.files.filter(file=>file.path.toLowerCase().includes(filter.value.toLowerCase()))??[]),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/30))),visible=computed(()=>filtered.value.slice((page.value-1)*30,page.value*30));
let generation=0;
async function load(){const current=++generation;loading.value=true;error.value='';preview.value=undefined;confirmation.value='';page.value=1;try{const branches=await request<BranchItem[]>(props.base+'/branches'),head=branches.find(branch=>branch.name===props.branch)?.commitId;if(!head)throw new Error('当前分支不存在，请刷新版本。');const value=await post<RepositoryVersionRestorePreview>(props.base+'/history/restore/preview',{ref:props.branch,expectedCommit:head,targetCommit:props.targetCommit});if(current!==generation)return;preview.value=value;message.value='Restore dataset to '+props.targetCommit.slice(0,12);}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function restore(){if(!preview.value||confirmation.value!==confirmValue.value||busy.value||uncertain.value)return;const current=generation;busy.value=true;error.value='';try{const result=await post<RepositoryVersionRestoreResult>(props.base+'/history/restore',{ref:props.branch,expectedCommit:preview.value.expectedCommit,targetCommit:props.targetCommit,planHash:preview.value.planHash,confirmation:confirmation.value,message:message.value});if(current!==generation)return;app.notify('已创建恢复提交，历史保留；恢复内容需要重新复核。');emit('restored',result);}catch(cause){if(current===generation){error.value=(cause as Error).message;if(cause instanceof ApiError&&(cause.status>=500||cause.code==='NETWORK_RESULT_UNKNOWN'||cause.code==='OPERATION_RECONCILIATION_REQUIRED')){uncertain.value=true;uncertainId.value=cause.operationId??'';}}}finally{if(current===generation)busy.value=false;}}
function close(){if(!busy.value)emit('close');}
watch(()=>[props.base,props.branch,props.targetCommit],()=>{uncertain.value=false;void load();},{immediate:true});watch(filter,()=>{page.value=1;});
const unregister=app.registerDraftGuard(async()=>{if(!busy.value)return true;app.notify('恢复提交仍在执行，请先等待或核对操作结果。');return false;});onBeforeUnmount(()=>{generation++;unregister();});
</script>
<template>
 <div class="restore-backdrop" @click.self="close"><section class="restore-dialog" role="dialog" aria-modal="true" aria-labelledby="restore-title" @keydown.esc="close">
  <header><div><h2 id="restore-title"><RotateCcw :size="20"/>恢复到此版本</h2><p>新增恢复提交 · 保留已有历史</p></div><button class="icon-button" aria-label="关闭版本恢复" :disabled="busy" @click="close"><X :size="19"/></button></header>
  <div class="restore-body"><div v-if="loading" class="empty" role="status"><LoaderCircle class="spinning"/>正在核对完整文件树、权限与恢复计划…</div>
   <div v-if="error" class="error-state" role="alert">{{error}}<button v-if="!uncertain" class="btn btn-ghost" :disabled="busy||loading" @click="load">重新预览</button></div>
   <p v-if="uncertain" class="restore-warning">结果尚未确认。自定义提交说明、目标和基点仍保留在此页。请<RouterLink to="/operations" target="_blank" rel="noopener">在新页打开操作核对</RouterLink>检查固定提交标记，不要重复提交。<span v-if="uncertainId">操作ID：<code>{{uncertainId}}</code></span></p>
   <template v-if="preview"><p class="restore-context"><strong>{{project}} / {{branch}}</strong><br/>当前 <code>{{preview.expectedCommit}}</code><br/>目标 <code>{{preview.targetCommit}}</code></p>
    <ul class="restore-warning"><li v-for="warning in preview.warnings" :key="warning">{{warning}}</li><li v-if="preview.preservedPaths.length">保留当前访问策略：{{preview.preservedPaths.join('、')}}</li></ul>
    <div class="restore-files-heading"><strong>{{preview.files.length}} 个文件变化</strong><input v-model="filter" aria-label="筛选恢复文件" placeholder="筛选文件路径…"/></div>
    <div class="restore-table"><table><thead><tr><th>动作</th><th>文件</th><th>核对依据</th></tr></thead><tbody><tr v-for="file in visible" :key="file.path"><td>{{({added:'新增',modified:'修改',removed:'删除'})[file.status]}}</td><td><code>{{file.path}}</code></td><td>{{file.generated?'本次操作时间/人员重新记录':(file.afterSha256??file.beforeSha256)?.slice(0,12)}}</td></tr></tbody></table></div>
    <nav v-if="pages>1" class="restore-pages" aria-label="恢复计划分页"><button class="btn btn-ghost" :disabled="page<=1" @click="page--">上一页</button><span>{{page}} / {{pages}} · 匹配{{filtered.length}}项</span><button class="btn btn-ghost" :disabled="page>=pages" @click="page++">下一页</button></nav>
    <p v-if="!preview.canRestore" class="muted">可恢复内容与当前版本相同，无需创建提交。</p>
    <form @submit.prevent><label>提交说明<input v-model="message" aria-label="恢复提交说明" maxlength="4000" :disabled="busy||uncertain"/></label><label>输入 <code>{{confirmValue}}</code> 确认恢复<input v-model="confirmation" aria-label="确认恢复的项目和分支" :placeholder="confirmValue" autocomplete="off" :disabled="busy||uncertain"/></label><footer><button type="button" class="btn btn-ghost" :disabled="busy" @click="close">取消</button><button type="button" class="btn btn-primary" @click="restore" :disabled="busy||uncertain||!preview.canRestore||confirmation!==confirmValue||!message.trim()"><LoaderCircle v-if="busy" class="spinning" :size="15"/>{{busy?'正在创建恢复提交…':'创建恢复提交'}}</button></footer></form>
   </template>
  </div>
 </section></div>
</template>
<style scoped>
.restore-backdrop{position:fixed;inset:0;z-index:110;background:var(--workbench-overlay);display:grid;place-items:center;padding:24px}.restore-dialog{width:min(900px,100%);max-height:calc(100dvh - 48px);overflow:auto;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius)}.restore-dialog>header{display:flex;justify-content:space-between;gap:15px;padding:20px;border-bottom:1px solid var(--line)}.restore-dialog h2{font-size:19px;display:flex;align-items:center;gap:9px;margin:0}.restore-dialog header p{color:var(--muted);font-size:13px;margin:8px 0 0}.restore-body{padding:20px}.restore-context{font-size:13px;line-height:1.9;overflow-wrap:anywhere}.restore-warning{padding:14px 16px;background:var(--surface-raised);border:1px solid var(--line);border-radius:var(--radius);font-size:13px;line-height:1.8;margin:16px 0}.restore-warning li{margin-left:14px}.restore-warning a{color:var(--primary)}.restore-files-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;font-size:14px;margin:15px 0}.restore-dialog input{padding:9px 11px;border:1px solid var(--line);background:var(--bg);color:var(--text);border-radius:var(--radius);min-width:0;font:inherit}.restore-files-heading input{max-width:50%}.restore-table{max-height:300px;overflow:auto;border:1px solid var(--line);border-radius:var(--radius)}.restore-table table{width:100%;border-collapse:collapse;text-align:left;font-size:var(--workbench-table-font-size);line-height:var(--workbench-table-line-height)}.restore-table th,.restore-table td{vertical-align:middle;padding:11px 12px;border-bottom:1px solid var(--line)}.restore-table th{font-size:var(--workbench-table-header-size);color:var(--muted);position:sticky;top:0;background:var(--surface-raised)}.restore-table td:nth-child(2){overflow-wrap:anywhere}.restore-pages{display:flex;justify-content:center;align-items:center;gap:10px;font-size:13px;padding:12px}.restore-dialog form{margin-top:20px;display:grid;gap:15px}.restore-dialog label{display:flex;flex-direction:column;gap:7px;font-size:13px}.restore-dialog footer{display:flex;justify-content:flex-end;gap:10px}.restore-dialog .error-state{margin:0 0 15px}@media(max-width:650px){.restore-backdrop{padding:10px}.restore-dialog{max-height:calc(100dvh - 20px)}.restore-dialog>header,.restore-body{padding:16px}.restore-files-heading{flex-wrap:wrap}.restore-files-heading input{max-width:100%;width:100%}.restore-table th,.restore-table td{padding:9px 8px}.restore-dialog footer{flex-wrap:wrap}}
</style>
